-- chair-step: inverse of read_lane_v2_b2_06_workspace_tasks — un-enrolls workspace.tasks from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workspace' and table_name = 'tasks' and is_active);
select iam.apply_rls('workspace', 'tasks', (select token from platform.entity_types where schema_name = 'workspace' and table_name = 'tasks' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workspace' and table_name = 'tasks' and is_active));
